mapper.select:
SELECT lodging.*, ( SELECT ROUND(AVG(rv_rating), 1) FROM review join room on rm_num = rv_number WHERE rv_table_name = 'room' AND rm_ld_num = lodging.LD_NUM ) AS avg_rating, MIN(t.rm_price) AS min_price, (select TH_UPLOAD from thumbnail where TH_TABLE="lodging" and th_key =lodging.ld_num limit 1) as main_thumbnail, (select th_name from thumbnail where TH_TABLE="lodging" and th_key =ld_num limit 1) as th_name FROM lodging JOIN ( SELECT * FROM room LEFT JOIN ( SELECT lr_rm_num, COUNT(lr_rm_num) AS count FROM lo_reservation WHERE ( LR_CHECKOUT BETWEEN DATE_ADD(#{lr_checkin}, INTERVAL 1 DAY) AND #{lr_checkout} ) OR ( LR_CHECKIN BETWEEN #{lr_checkin} AND DATE_SUB(#{lr_checkout}, INTERVAL 1 DAY) ) OR( LR_CHECKIN <= #{lr_checkin} and LR_CHECKOUT >= #{lr_checkout} ) AND LR_STATE = '예약완료' GROUP BY lr_rm_num ) AS tmp_lo_reservation ON lr_rm_num = rm_num WHERE RM_ROOMCOUNT - IFNULL(count, 0) > 0 AND rm_person >= #{rm_person} ) t ON rm_ld_num = ld_num JOIN region ON rg_num = LD_RG_NUM WHERE rg_name = #{cri.rg_name}
and ld_rating IN
#{rating}
and ld_type IN
#{type}
AND ld_name LIKE CONCAT('%', #{cri.ld_name}, '%')
GROUP BY lodging.LD_NUM having 1=1
and avg_rating >= #{cri.avg}
and min_price <= #{cri.price} *10000
ORDER BY avg_rating DESC
ORDER BY min_price ASC
ORDER BY ld_rating DESC

select do_num
from default_option
where do_name = #{do_name}
